-- Generated from https://github.com/edificeio/stats-events-schema/blob/45150d1991d53890676cfc304b90eaf4c6627ac7/src/main/resources/schema/events/stats.json
-- with the same rules as com.opendigitaleducation.events.postgresql.PgEventsManager#createTableIfNotExists (edificeio/pg-events).
-- Schemas and tables are created only when missing: the script can run on a database where they were already installed.

CREATE SCHEMA IF NOT EXISTS events;
CREATE SCHEMA IF NOT EXISTS external;
CREATE SCHEMA IF NOT EXISTS repository;
CREATE SCHEMA IF NOT EXISTS stats;
CREATE SCHEMA IF NOT EXISTS utils;

CREATE TABLE IF NOT EXISTS stats.scripts (filename VARCHAR(255) NOT NULL PRIMARY KEY, passed TIMESTAMP NOT NULL DEFAULT now());

CREATE TABLE IF NOT EXISTS events.login_events ( id UUID NOT NULL, date TIMESTAMP NOT NULL, profile VARCHAR(9), module VARCHAR(64), event_type VARCHAR(16), ua VARCHAR(256), device_type VARCHAR(32), platform_id VARCHAR(36), user_id VARCHAR(36), ip inet, useradmin VARCHAR(11)) PARTITION BY RANGE (date);
CREATE TABLE IF NOT EXISTS events.access_events ( id UUID NOT NULL, date TIMESTAMP NOT NULL, profile VARCHAR(9), module VARCHAR(64), event_type VARCHAR(16), ua VARCHAR(256), device_type VARCHAR(32), platform_id VARCHAR(36), user_id VARCHAR(36), ip inet) PARTITION BY RANGE (date);
CREATE TABLE IF NOT EXISTS events.create_events ( id UUID NOT NULL, date TIMESTAMP NOT NULL, profile VARCHAR(9), module VARCHAR(64), event_type VARCHAR(16), ua VARCHAR(256), device_type VARCHAR(32), platform_id VARCHAR(36), user_id VARCHAR(36), resource_type VARCHAR(64), migration_id TEXT, ip inet) PARTITION BY RANGE (date);
CREATE TABLE IF NOT EXISTS events.connector_events ( id UUID NOT NULL, date TIMESTAMP NOT NULL, profile VARCHAR(9), module VARCHAR(64), event_type VARCHAR(16), "connector-type" VARCHAR(16), service VARCHAR(256), ua VARCHAR(256), device_type VARCHAR(32), platform_id VARCHAR(36), user_id VARCHAR(36), "cas-type" VARCHAR(256), ip inet) PARTITION BY RANGE (date);
CREATE TABLE IF NOT EXISTS events.activation_events ( id UUID NOT NULL, date TIMESTAMP NOT NULL, profile VARCHAR(9), module VARCHAR(64), event_type VARCHAR(16), ua VARCHAR(256), device_type VARCHAR(32), sync BOOLEAN, platform_id VARCHAR(36), user_id VARCHAR(36), ip inet) PARTITION BY RANGE (date);
CREATE TABLE IF NOT EXISTS events.room_access_events ( id UUID NOT NULL, date TIMESTAMP NOT NULL, profile VARCHAR(9), module VARCHAR(64), event_type VARCHAR(16), ua VARCHAR(256), device_type VARCHAR(32), platform_id VARCHAR(36), user_id VARCHAR(36), ip inet) PARTITION BY RANGE (date);
CREATE TABLE IF NOT EXISTS events.room_creation_events ( id UUID NOT NULL, date TIMESTAMP NOT NULL, profile VARCHAR(9), module VARCHAR(64), event_type VARCHAR(16), ua VARCHAR(256), device_type VARCHAR(32), platform_id VARCHAR(36), user_id VARCHAR(36), ip inet) PARTITION BY RANGE (date);
CREATE TABLE IF NOT EXISTS events.sms_events ( id UUID NOT NULL, date TIMESTAMP NOT NULL, profile VARCHAR(9), module VARCHAR(64), event_type VARCHAR(16), ua VARCHAR(256), device_type VARCHAR(32), platform_id VARCHAR(36), user_id VARCHAR(36), ip inet, sms_id VARCHAR(34), phone VARCHAR(16)) PARTITION BY RANGE (date);
CREATE TABLE IF NOT EXISTS events.creation_events ( id UUID NOT NULL, date TIMESTAMP NOT NULL, profile VARCHAR(9), module VARCHAR(64), event_type VARCHAR(16), resource_type VARCHAR(64), size BIGINT, ua VARCHAR(256), device_type VARCHAR(32), platform_id VARCHAR(36), user_id VARCHAR(36), ip inet) PARTITION BY RANGE (date);
