CREATE TABLE IF NOT EXISTS events.auth_events ( id UUID NOT NULL, date TIMESTAMP NOT NULL, external_id VARCHAR(64), profile VARCHAR(9), login VARCHAR(64), login_alias VARCHAR(64), password VARCHAR(32), event_type VARCHAR(16), sync BOOLEAN, platform_id VARCHAR(36), user_id VARCHAR(36), ip inet) PARTITION BY RANGE (date);
CREATE TABLE IF NOT EXISTS events.edit_start_events ( id UUID NOT NULL, date TIMESTAMP NOT NULL, profile VARCHAR(9), module VARCHAR(64), event_type VARCHAR(16), ua VARCHAR(256), device_type VARCHAR(32), platform_id VARCHAR(36), user_id VARCHAR(36), resource_type VARCHAR(64), resource_id VARCHAR(36), resource_uri TEXT, ip inet) PARTITION BY RANGE (date);
CREATE TABLE IF NOT EXISTS events.edit_stop_events ( id UUID NOT NULL, date TIMESTAMP NOT NULL, profile VARCHAR(9), module VARCHAR(64), event_type VARCHAR(16), ua VARCHAR(256), device_type VARCHAR(32), platform_id VARCHAR(36), user_id VARCHAR(36), resource_type VARCHAR(64), resource_id VARCHAR(36), resource_uri TEXT, duration INTEGER, ip inet) PARTITION BY RANGE (date);
