CREATE TABLE IF NOT EXISTS repository.platforms (id VARCHAR(36) PRIMARY KEY,external_id VARCHAR(40),created TIMESTAMP,modified TIMESTAMP,deleted TIMESTAMP,name VARCHAR(64)  NOT NULL);
CREATE TABLE IF NOT EXISTS repository.tenants (id VARCHAR(36) PRIMARY KEY,external_id VARCHAR(40),created TIMESTAMP,modified TIMESTAMP,deleted TIMESTAMP,name VARCHAR(64) NOT NULL,platform_id VARCHAR(36) REFERENCES repository.platforms(id));
CREATE TABLE IF NOT EXISTS repository.structures (id VARCHAR(36) PRIMARY KEY,external_id VARCHAR(64),uai VARCHAR(8),created TIMESTAMP,modified TIMESTAMP,deleted TIMESTAMP,name VARCHAR(128) NOT NULL,source VARCHAR(6),child_structures VARCHAR(36) [],parent_structures VARCHAR(36) [],platform_id VARCHAR(36) REFERENCES repository.platforms(id),tenant_id VARCHAR(36) REFERENCES repository.tenants(id));
